// Some portions generated by Codex
const { test, expect } = require('@playwright/test');
const {
    deleteRepository, memoryRepositoryConfiguration, repositoryPageUrl, serverBaseUrl, uniqueRepositoryId, waitForRoute
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('configuration-editor');
let fixtureCreated = false;

test.beforeAll(async ({ request }) => {
    if (!process.env.RDF4J_SERVER_BASE_URL || !process.env.RDF4J_WORKBENCH_BASE_URL) {
        throw new Error('Set RDF4J_SERVER_BASE_URL and RDF4J_WORKBENCH_BASE_URL to the isolated test server.');
    }
    // PUT creates only: the server returns conflict for an existing ID, so an unsuccessful setup never arms cleanup.
    const created = await request.put(`${serverBaseUrl()}/repositories/${encodeURIComponent(REPOSITORY_ID)}`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Configuration editor browser fixture')
    });
    expect([200, 201, 204]).toContain(created.status());
    fixtureCreated = true;
});

test.afterAll(async ({ request }) => {
    if (fixtureCreated) {
        await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
    }
});

async function editorValue(page) {
    return page.locator('#configuration-editor .CodeMirror').evaluate(element => element.CodeMirror.getValue());
}

async function setEditor(page, value) {
    await page.locator('#configuration-editor .CodeMirror').evaluate((element, text) => {
        element.CodeMirror.setValue(text);
    }, value);
}

async function expectFreshReload(page, freezeSavedModel, submitInvalid = true) {
    const initialResponse = page.waitForResponse(response => response.request().method() === 'GET'
        && new URL(response.url()).pathname.endsWith('/config')
        && (response.request().headers().accept || '').includes('application/vnd.rdf4j.workbench+ndjson'));
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'config'));
    await waitForRoute(page, 'config');
    const savedModel = await (await initialResponse).text();
    await expect(page.locator('#configuration-editor .CodeMirror')).toBeVisible();
    const saved = await editorValue(page);
    expect(saved).toContain(REPOSITORY_ID);
    const invalid = saved + '\n<urn:discarded-configuration-draft> <urn:predicate> "unterminated';
    await setEditor(page, invalid);
    if (submitInvalid) {
        const refused = page.waitForResponse(response => response.request().method() === 'POST'
            && new URL(response.url()).pathname.endsWith('/config'));
        await page.getByRole('button', { name: 'Save', exact: true }).click();
        expect((await refused).status()).toBe(400);
        await waitForRoute(page, 'config');
        await expect(page.locator('#configuration-form')).toContainText('Unexpected end of file');
    }
    await expect.poll(() => editorValue(page)).toBe(invalid);
    await page.evaluate(() => { window.configurationReloadDocumentMarker = 'same-document'; });
    if (freezeSavedModel) {
        await page.route(url => url.pathname.endsWith(`/repositories/${REPOSITORY_ID}/config`), async route => {
            if (route.request().method() === 'GET'
                    && (route.request().headers().accept || '').includes('application/vnd.rdf4j.workbench+ndjson')) {
                await route.fulfill({ status: 200,
                    contentType: 'application/vnd.rdf4j.workbench+ndjson; charset=UTF-8', body: savedModel });
            } else {
                await route.continue();
            }
        });
    }
    const fresh = page.waitForResponse(response => response.request().method() === 'GET'
        && new URL(response.url()).pathname.endsWith('/config')
        && (response.request().headers().accept || '').includes('application/vnd.rdf4j.workbench+ndjson'));

    await page.getByRole('link', { name: 'Reload saved configuration', exact: true }).click();
    const reloaded = await fresh;
    expect(reloaded.status()).toBe(200);
    const freshModel = await reloaded.text();
    if (freezeSavedModel) {
        expect(freshModel, 'the entire server model is byte-identical, including blank-node IDs').toBe(savedModel);
    }
    const records = freshModel.trim().split('\n').map(line => JSON.parse(line));
    const variables = records.find(record => record.type === 'vars').values;
    const freshTurtle = records.find(record => record.type === 'rows').values[0][variables.indexOf('configuration')].value;
    expect(freshTurtle).not.toContain('urn:discarded-configuration-draft');
    await waitForRoute(page, 'config');

    await expect.poll(() => editorValue(page)).toBe(freshTurtle);
    await expect(page.locator('#configuration')).toHaveValue(freshTurtle);
    await expect(page.locator('#configuration-form')).not.toContainText('Unexpected end of file');
    expect(await page.evaluate(() => window.configurationReloadDocumentMarker)).toBe('same-document');
}

test('Reload saved configuration discards a rejected draft through the same-URL router', async ({ page }) => {
    await expectFreshReload(page, false);
});

test('Reload discards an unsaved draft even when successive saved page models are byte-identical', async ({ page }) => {
    await expectFreshReload(page, true, false);
});

test('submission-status rerenders retain the current configuration editor text', async ({ page }) => {
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'config'));
    await waitForRoute(page, 'config');
    await expect(page.locator('#configuration-editor .CodeMirror')).toBeVisible();
    const draft = await editorValue(page) + '\n# Keep this editor text while the save status changes\n';
    await setEditor(page, draft);

    await page.getByRole('button', { name: 'Save', exact: true }).click();
    const status = page.locator('#configuration-form .workbench-submit-status');
    await expect(status).toHaveAttribute('data-state', 'done');
    await expect.poll(() => editorValue(page)).toBe(draft);
    const next = draft + '\n# A further unsaved change\n';
    await setEditor(page, next);

    await expect(status).toHaveAttribute('data-state', 'idle');
    await expect.poll(() => editorValue(page)).toBe(next);
    await expect(page.locator('#configuration')).toHaveValue(next);
});

test('ordinary navigation and Back preserve the configuration draft', async ({ page }) => {
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'config'));
    await waitForRoute(page, 'config');
    await expect(page.locator('#configuration-editor .CodeMirror')).toBeVisible();
    const draft = await editorValue(page) + '\n# Keep this draft through Back\n';
    await setEditor(page, draft);
    await page.getByRole('link', { name: 'Summary', exact: true }).first().click();
    await waitForRoute(page, 'summary');

    await page.goBack();
    await waitForRoute(page, 'config');

    await expect.poll(() => editorValue(page)).toBe(draft);
});
